6	
7	/// LibrePili privacy model: incognito by default, login is opt-in, and even
8	/// in login mode the account is attached only to requests that need it.
9	///
10	/// Everything else (recommend, search, video info, comments, spaces...) is
11	/// sent anonymously so it cannot be tied to the account.
12	abstract final class LoginPolicy {
13	  /// Opt-in switch. Off: every account role is anonymous (stored accounts
14	  /// stay dormant). On: see [requiresAccount].
15	  static bool get loginMode => Pref.loginMode;
16	
17	  /// Account-private reads, app-API writes (signed with access_key instead of
18	  /// csrf), login-flow calls and stream URLs (high quality needs an account).
