   140	    if (options.responseType == ResponseType.stream) {
   141	      return handler.next(err);
   142	    }
   143	
   144	    if (options.method != 'POST') toast(err);
   145	
   146	    if (err.response case final res?) {
   147	      if (_boundRequestAccount(options) case final account?) {
   148	        _saveCookies(account, res).then(
   149	          (_) => handler.next(err),
   150	          onError: (Object e, StackTrace s) => handler.next(
   151	            DioException(
   152	              requestOptions: options,
   153	              error: e,
   154	              stackTrace: s,
   155	            ),
   156	          ),
   157	        );
   158	        return;
   159	      }
   160	    }
   161	    return handler.next(err);
   162	  }
   163	
   164	  static void toast(DioException err) {
   165	    const skipShow = [
   166	      'heartbeat',
   167	      'history/report',
   168	      'roomEntryAction',
   169	      'seg.so',
   170	      'online/total',
   171	      'github',
   172	      'hdslb.com',
   173	      'biliimg.com',
   174	      'site/getCoin',
   175	    ];
   176	    String url = err.requestOptions.uri.toString();
   177	    if (kDebugMode) debugPrint('🌹🌹ApiInterceptor: $url\n$err');
   178	    if (skipShow.any(url.contains) ||
   179	        (url.contains('skipSegments') && err.requestOptions.method == 'GET')) {
   180	      // skip
   181	    } else {
   182	      dioError(err).then((res) => SmartDialog.showToast(res + url));
   183	    }
   184	  }
   185	
   186	  static Future<void> _saveCookies(Account account, Response response) async {
   187	    final setCookies = response.headers[HttpHeaders.setCookieHeader];
   188	    if (setCookies == null || setCookies.isEmpty) {
   189	      return;
   190	    }
   191	    final List<Cookie> cookies = setCookies
   192	        .map((str) => str.split(_setCookieReg))
   193	        .expand((cookie) => cookie)
   194	        .where((cookie) => cookie.isNotEmpty)
   195	        .map(Cookie.fromSetCookieValue)
   196	        .toList();
   197	    final statusCode = response.statusCode ?? 0;
   198	    final locations = response.headers[HttpHeaders.locationHeader] ?? const [];
   199	    final isRedirectRequest = statusCode >= 300 && statusCode < 400;
   200	    final originalUri = response.requestOptions.uri;
   201	    final realUri = originalUri.resolveUri(response.realUri);
   202	    await account.cookieJar.saveFromResponse(realUri, cookies);
   203	    if (isRedirectRequest && locations.isNotEmpty) {
   204	      final originalUri = response.realUri;
   205	      await Future.wait(
   206	        locations.map(
   207	          (location) => account.cookieJar.saveFromResponse(
   208	            // Resolves the location based on the current Uri.
   209	            originalUri.resolve(location),
   210	            cookies,
   211	          ),
   212	        ),
   213	      );
   214	    }
   215	    await account.onChange();
   216	  }
