   218	  static bool _skipCookie(String path) {
   219	    return path.startsWith(blockServer) ||
   220	        path.contains('hdslb.com') ||
   221	        path.contains('biliimg.com');
   222	  }
   223	
   224	  static Account _findAccount(String path) => ApiType.loginApi.contains(path)
   225	      ? AnonymousAccount()
   226	      : Accounts.get(
   227	          AccountType.values.firstWhere(
   228	            (i) => ApiType.apiTypeSet[i]?.contains(path) == true,
   229	            orElse: () => AccountType.main,
   230	          ),
   231	        );
   232	
   233	  static Account _bindRequestAccount(RequestOptions options) {
   234	    assert(options.extra['account'] is Account?);
   235	    var account =
   236	        options.extra['account'] as Account? ?? _findAccount(options.path);
   237	    // LibrePili: no global login. Even in login mode the account is only
   238	    // attached where it is required; everything else goes out anonymously.
   239	    if (account is LoginAccount &&
   240	        (!LoginPolicy.loginMode || !LoginPolicy.requiresAccount(options))) {
   241	      account = AnonymousAccount();
   242	    }
   243	    return options.extra['account'] = account;
   244	  }
   245	
   246	  static Account? _boundRequestAccount(RequestOptions options) {
   247	    final path = options.path;
   248	    final account = options.extra['account'] as Account;
   249	    if (account is NoAccount ||
   250	        path.startsWith(HttpString.appBaseUrl) ||
   251	        _skipCookie(path)) {
   252	      return null;
   253	    }
   254	    return account;
   255	  }
