   257	  static Future<String> dioError(DioException error) async {
   258	    switch (error.type) {
   259	      case .badCertificate:
   260	        return '证书有误！';
   261	      case .badResponse:
   262	        return '服务器异常，请稍后重试！';
   263	      case .cancel:
   264	        return '请求已被取消，请重新请求';
   265	      case .connectionError:
   266	        return '连接错误，请检查网络设置';
   267	      case .connectionTimeout:
