 31	      compactionStrategy: (int entries, int deletedEntries) {
 32	        return deletedEntries > 2;
 33	      },
 34	    );
 35	  }
 36	
 37	  static Future<void> refresh() {
 38	    for (int i = 0; i < AccountType.values.length; i++) {
 39	      accountMode[i] = AnonymousAccount();
 40	    }
 41	    // LibrePili: stored accounts stay dormant unless login mode is on
 42	    if (LoginPolicy.loginMode) {
 43	      for (final a in account.values) {
 44	        for (final t in a.type) {
 45	          accountMode[t.index] = a;
 46	        }
 47	      }
 48	    }
 49	    return Future.wait(
 50	      (accountMode.toSet()..removeWhere((i) => i.activated)).map(
 51	        Request.buvidActive,
 52	      ),
 53	    );
 54	  }
 55	
 56	  static Future<void> clear() async {
 57	    await account.clear();
 58	    for (int i = 0; i < AccountType.values.length; i++) {
 59	      accountMode[i] = AnonymousAccount();
 60	    }
 61	    await AnonymousAccount().delete();
 62	    Request.buvidActive(AnonymousAccount());
 63	  }
 64	
 65	  static Future<void> deleteAll(Set<Account> accounts) async {
 66	    final isLoginMain = Accounts.main.isLogin;
 67	    for (int i = 0; i < AccountType.values.length; i++) {
 68	      if (accounts.contains(accountMode[i])) {
 69	        accountMode[i] = AnonymousAccount();
 70	      }
 71	    }
 72	    await Future.wait(accounts.map((i) => i.delete()));
 73	    if (isLoginMain && !Accounts.main.isLogin) {
 74	      await LoginUtils.onLogoutMain();
 75	    }
 76	  }
