 78	  static Future<void> set(AccountType key, Account account) async {
 79	    final oldAccount = accountMode[key.index]..type.remove(key);
 80	    accountMode[key.index] = account..type.add(key);
 81	    await Future.wait([?account.onChange(), ?oldAccount.onChange()]);
 82	    if (!LoginPolicy.loginMode) {
 83	      // role is saved on the account but stays dormant until login mode
 84	      accountMode[key.index] = AnonymousAccount();
 85	      return;
 86	    }
 87	    if (!account.activated) await Request.buvidActive(account);
 88	    switch (key) {
