308	    required BiliDownloadEntryInfo entry,
309	    bool isUpdate = false,
310	  }) async {
311	    final cid = entry.pageData?.cid ?? entry.source?.cid;
312	    if (cid == null) {
313	      return false;
314	    }
315	    final danmakuFile = File(
316	      path.join(entry.entryDirPath, PathUtils.danmakuName),
317	    );
318	    if (isUpdate || !danmakuFile.existsSync()) {
319	      try {
320	        if (!isUpdate) {
321	          _updateCurStatus(DownloadStatus.getDanmaku);
322	        }
