328	        final danmaku = (await DmGrpc.dmSegMobile(
329	          cid: cid,
330	          segmentIndex: 1,
331	        )).data;
332	        for (var start = 2; start <= seg; start += _maxDanmakuConcurrency) {
333	          final end = start + _maxDanmakuConcurrency - 1;
334	          final responses = await Future.wait([
335	            for (var index = start; index <= seg && index <= end; index++)
336	              DmGrpc.dmSegMobile(cid: cid, segmentIndex: index),
337	          ]);
338	          for (final response in responses) {
339	            danmaku.elems.addAll(response.data.elems);
340	          }
341	          responses.clear();
342	        }
343	        await danmakuFile.writeAsBytes(danmaku.writeToBuffer());
344	
345	        return true;
346	      } catch (e) {
347	        if (!isUpdate) {
348	          _updateCurStatus(DownloadStatus.failDanmaku);
349	        }
350	        if (kDebugMode) SmartDialog.showToast(e.toString());
351	        return false;
352	      }
353	    }
354	    return true;
355	  }
