264	  static Future<_Track> parse(String path) async {
265	    final t = _Track(path);
266	    final raf = await File(path).open();
267	    try {
268	      final length = await raf.length();
269	      var pos = 0;
270	      var sawMoov = false;
271	      var dts = 0;
272	      while (pos + 8 <= length) {
273	        await raf.setPosition(pos);
274	        final header = await raf.read(16);
275	        final hd = ByteData.sublistView(header);
276	        var size = hd.getUint32(0);
277	        final type = String.fromCharCodes(header, 4, 8);
278	        var headerSize = 8;
279	        if (size == 1) {
280	          size = hd.getUint64(8);
281	          headerSize = 16;
282	        } else if (size == 0) {
283	          size = length - pos;
284	        }
285	        if (size < headerSize || pos + size > length) {
286	          throw FormatException('bad box $type at $pos in $path');
287	        }
288	        if (type == 'moov') {
289	          await raf.setPosition(pos + headerSize);
290	          t._parseMoov(await raf.read(size - headerSize));
291	          sawMoov = true;
