626	    final entries = <(int, int)>[];
627	    for (var i = 0; i < chunks.length; i++) {
628	      final n = chunks[i].sampleCount;
629	      if (entries.isEmpty || entries.last.$2 != n) entries.add((i + 1, n));
630	    }
631	    final w = _W()
632	      ..u32(0)
633	      ..u32(entries.length);
634	    for (final (firstChunk, perChunk) in entries) {
635	      w
636	        ..u32(firstChunk)
637	        ..u32(perChunk)
638	        ..u32(1);
639	    }
640	    return _box('stsc', w.bytes);
641	  }
642	
643	  Uint8List _stco(bool co64) {
644	    final w = _W()
645	      ..u32(0)
646	      ..u32(chunks.length);
647	    for (final c in chunks) {
648	      co64 ? w.u64(c.outputOffset) : w.u32(c.outputOffset);
649	    }
650	    return _box(co64 ? 'co64' : 'stco', w.bytes);
651	  }
652	}
653	
654	int _scale(int value, int from, int to) =>
655	    from == to ? value : (value * to + from ~/ 2) ~/ from;
656	
657	Uint8List _box(String type, Uint8List body) {
658	  final size = body.length + 8;
659	  final w = _W();
660	  if (size > 0xFFFFFFFF) {
661	    w
662	      ..u32(1)
663	      ..fourcc(type)
664	      ..u64(size + 8);
665	  } else {
666	    w
667	      ..u32(size)
668	      ..fourcc(type);
669	  }
670	  return _concat([w.bytes, body]);
671	}
672	
673	Uint8List _concat(List<Uint8List> parts) {
674	  final b = BytesBuilder(copy: false);
675	  parts.forEach(b.add);
676	  return b.takeBytes();
677	}
678	
679	class _W {
680	  final _b = BytesBuilder();
681	  final _tmp = ByteData(8);
682	  Uint8List get bytes => _b.toBytes();
683	
684	  void u16(int v) {
685	    _tmp.setUint16(0, v);
686	    _b.add(_tmp.buffer.asUint8List(0, 2));
687	  }
688	
689	  void u32(int v) {
690	    _tmp.setUint32(0, v & 0xFFFFFFFF);
691	    _b.add(_tmp.buffer.asUint8List(0, 4));
692	  }
693	
694	  void u64(int v) {
695	    _tmp.setUint64(0, v);
696	    _b.add(_tmp.buffer.asUint8List(0, 8));
697	  }
698	
699	  void i64(int v) {
700	    _tmp.setInt64(0, v);
701	    _b.add(_tmp.buffer.asUint8List(0, 8));
702	  }
703	
704	  void fourcc(String s) => _b.add(s.codeUnits);
705	  void zeros(int n) => _b.add(Uint8List(n));
706	  void bytes_(Uint8List data) => _b.add(data);
707	}
708	
709	class _R {
710	  _R(this.data) : _bd = ByteData.sublistView(data);
711	  final Uint8List data;
712	  final ByteData _bd;
713	  int pos = 0;
714	
715	  int u8() => _bd.getUint8(pos++);
716	  int u24() {
717	    final v = (_bd.getUint8(pos) << 16) | _bd.getUint16(pos + 1);
718	    pos += 3;
719	    return v;
720	  }
721	
722	  int u32() {
723	    final v = _bd.getUint32(pos);
724	    pos += 4;
725	    return v;
726	  }
727	
728	  int i32() {
729	    final v = _bd.getInt32(pos);
730	    pos += 4;
731	    return v;
732	  }
733	
734	  int u64() {
735	    final v = _bd.getUint64(pos);
736	    pos += 8;
737	    return v;
738	  }
739	
740	  int i64() {
741	    final v = _bd.getInt64(pos);
742	    pos += 8;
743	    return v;
744	  }
745	
746	  void skip(int n) => pos += n;
747	  Uint8List bytes(int n) {
748	    final v = Uint8List.sublistView(data, pos, pos + n);
749	    pos += n;
750	    return v;
751	  }
752	
753	  Uint8List rest() => Uint8List.sublistView(data, pos);
754	
755	  /// Iterates child boxes of the current buffer, yielding (type, body).
756	  Iterable<(String, Uint8List)> boxes() sync* {
757	    var p = 0;
758	    while (p + 8 <= data.length) {
759	      var size = _bd.getUint32(p);
760	      final type = String.fromCharCodes(data, p + 4, p + 8);
761	      var header = 8;
762	      if (size == 1) {
763	        size = _bd.getUint64(p + 8);
764	        header = 16;
765	      } else if (size == 0) {
766	        size = data.length - p;
767	      }
768	      if (size < header || p + size > data.length) {
769	        throw FormatException('bad box $type');
770	      }
771	      yield (type, Uint8List.sublistView(data, p + header, p + size));
772	      p += size;
773	    }
774	  }
775	}
