  void u32(int v) {
    _tmp.setUint32(0, v & 0xFFFFFFFF);
    _b.add(_tmp.buffer.asUint8List(0, 4));
  }

  void u64(int v) {
    _tmp.setUint64(0, v);
    _b.add(_tmp.buffer.asUint8List(0, 8));
  }

  void i64(int v) {
    _tmp.setInt64(0, v);
    _b.add(_tmp.buffer.asUint8List(0, 8));
