3	/// LibrePili: pure-Dart FLV demuxer feeding [Mp4Remuxer]'s progressive MP4
4	/// writer, for the old single-URL (durl) downloads.
5	///
6	/// FLV AVC payloads are already length-prefixed NAL units and AAC payloads
7	/// raw frames, which is exactly what MP4 samples hold, so sample bytes are
8	/// never decoded: every sample becomes a chunk pointing into its FLV file and
9	/// is copied byte-for-byte. Only H.264 video and AAC audio are supported;
10	/// anything else throws [UnsupportedError].
11	abstract final class _FlvDemuxer {
12	  /// A segment whose timestamps start this far before the end of what came
13	  /// earlier restarted its clock and is placed after it.
14	  static const _restartThresholdMs = 500;
15	
16	  static List<_Track> demux(List<String> inputs) {
17	    final video = _FlvTrackBuilder(isVideo: true);
18	    final audio = _FlvTrackBuilder(isVideo: false);
19	    for (final input in inputs) {
20	      final raf = File(input).openSync();
21	      try {
22	        final r = _FileReader(raf);
23	        final header = r.read(0, 9);
24	        if (String.fromCharCodes(header, 0, 3) != 'FLV') {
25	          throw FormatException('not an FLV file: $input');
26	        }
27	        // header, then PreviousTagSize0
28	        var pos = ByteData.sublistView(header).getUint32(5) + 4;
29	        int? offset; // ms added to this segment's timestamps
30	        while (pos + 11 <= r.length) {
31	          final h = r.read(pos, 11);
32	          final type = h[0];
33	          final dataSize = (h[1] << 16) | (h[2] << 8) | h[3];
34	          final ts = ((h[7] << 24) | (h[4] << 16) | (h[5] << 8) | h[6])
35	              .toSigned(32);
36	          final dataPos = pos + 11;
37	          if (dataPos + dataSize > r.length) break; // truncated last tag
38	          pos = dataPos + dataSize + 4; // + PreviousTagSize
39	          final kind = type & 0x1F;
40	          if ((kind != 8 && kind != 9) || dataSize == 0) continue;
41	          if (type & 0x20 != 0) throw UnsupportedError('encrypted FLV');
42	          if (offset == null) {
43	            final end = max(video.endMs, audio.endMs);
44	            offset = ts + _restartThresholdMs < end ? end - ts : 0;
45	          }
46	          final head = r.read(dataPos, min(dataSize, 5));
47	          final time = ts + offset;
48	          if (kind == 9) {
49	            video.addVideoTag(input, dataPos, dataSize, head, time, r);
50	          } else {
51	            audio.addAudioTag(input, dataPos, dataSize, head, time, r);
52	          }
53	        }
54	      } finally {
55	        raf.closeSync();
56	      }
57	    }
58	    final starts = [
59	      for (final b in [video, audio])
60	        if (b.times.isNotEmpty) b.times.first,
61	    ];
62	    if (starts.isEmpty) throw const FormatException('no audio/video in FLV');
63	    final base = starts.reduce(min);
64	    final tracks = <_Track>[];
65	    for (final b in [video, audio]) {
66	      if (b.build(base) case final t?) tracks.add(t..index = tracks.length);
67	    }
68	    return tracks;
69	  }
70	}
71	
72	class _FlvTrackBuilder {
73	  _FlvTrackBuilder({required this.isVideo});
74	
75	  final bool isVideo;
76	
77	  /// AVCDecoderConfigurationRecord / AudioSpecificConfig.
78	  Uint8List? config;
79	
80	  // per sample, in decode order
81	  final times = <int>[]; // ms
82	  final ctsMs = <int>[];
83	  final keys = <bool>[];
84	  final paths = <String>[];
85	  final offsets = <int>[];
86	  final sizes = <int>[];
87	
88	  int get _defaultDurationMs => isVideo ? 40 : 23;
89	
90	  int get _lastDurationMs => times.length < 2
91	      ? _defaultDurationMs
92	      : times.last - times[times.length - 2];
93	
94	  /// Where the next sample of a following segment would start.
95	  int get endMs => times.isEmpty ? 0 : times.last + _lastDurationMs;
96	
97	  void addVideoTag(
98	    String path,
99	    int dataPos,
100	    int dataSize,
101	    Uint8List head,
102	    int time,
103	    _FileReader r,
104	  ) {
105	    final codec = head[0] & 0x0F;
106	    // bit 7: enhanced FLV (HEVC / AV1 ...)
107	    if (head[0] & 0x80 != 0 || codec != 7) {
108	      throw UnsupportedError('FLV video codec $codec (only H.264)');
109	    }
110	    if (dataSize <= 5) return;
111	    switch (head[1]) {
112	      case 0: // sequence header
113	        _setConfig(r.read(dataPos + 5, dataSize - 5));
114	      case 1: // NAL units
115	        final cts = ((head[2] << 16) | (head[3] << 8) | head[4]).toSigned(24);
116	        _add(path, dataPos + 5, dataSize - 5, time, cts, head[0] >> 4 == 1);
117	    }
118	  }
119	
120	  void addAudioTag(
121	    String path,
122	    int dataPos,
123	    int dataSize,
124	    Uint8List head,
125	    int time,
126	    _FileReader r,
127	  ) {
128	    final format = head[0] >> 4;
129	    if (format != 10) {
130	      throw UnsupportedError('FLV audio codec $format (only AAC)');
131	    }
132	    if (dataSize <= 2) return;
133	    switch (head[1]) {
134	      case 0: // AudioSpecificConfig
135	        _setConfig(r.read(dataPos + 2, dataSize - 2));
136	      case 1: // raw frame
137	        _add(path, dataPos + 2, dataSize - 2, time, 0, true);
138	    }
139	  }
140	
141	  void _setConfig(Uint8List c) {
142	    final old = config;
143	    if (old == null) {
144	      config = Uint8List.fromList(c);
145	      return;
146	    }
147	    var same = old.length == c.length;
148	    for (var i = 0; same && i < c.length; i++) {
149	      same = old[i] == c[i];
150	    }
151	    // repeated at segment starts; a real change would need a second stsd
152	    if (!same) {
153	      throw UnsupportedError('codec configuration changes mid-stream');
154	    }
155	  }
156	
157	  void _add(String path, int offset, int size, int time, int cts, bool key) {
158	    if (config == null) return; // undecodable before the sequence header
159	    if (times.isNotEmpty && time <= times.last) time = times.last + 1;
160	    times.add(time);
161	    ctsMs.add(cts);
162	    keys.add(key);
163	    paths.add(path);
164	    offsets.add(offset);
165	    sizes.add(size);
166	  }
167	
168	  /// [baseMs]: earliest start of all tracks; a later start becomes an empty
169	  /// edit so audio and video stay in sync.
170	  _Track? build(int baseMs) {
171	    final config = this.config;
172	    if (config == null || sizes.isEmpty) return null;
173	    final t = _Track(paths.first)
174	      ..sourceMovieTimescale = 1000
175	      ..tkhdFlags = 0
176	      ..mdhdLanguage =
177	          Uint8List.fromList([0x55, 0xC4]) // und
178	      ..dinf = _box(
179	        'dinf',
180	        _box(
181	          'dref',
182	          (_W()
183	                ..u32(0)
184	                ..u32(1)
185	                ..bytes_(_box('url ', (_W()..u32(1)).bytes)))
186	              .bytes,
187	        ),
188	      );
189	    final Uint8List entry;
190	    if (isVideo) {
191	      final (width, height) = _avcDimensions(config);
192	      t
193	        ..timescale = 1000
194	        ..sampleEntryType = 'avc1'
195	        ..hdlr = _hdlr('vide', 'VideoHandler')
196	        ..mediaHeader = _box(
197	          'vmhd',
198	          (_W()
199	                ..u32(1)
200	                ..zeros(8))
201	              .bytes,
202	        )
203	        ..tkhdTail = _tkhdTail(0, width, height);
204	      entry = _box(
205	        'avc1',
206	        (_W()
207	              ..zeros(6)
208	              ..u16(1) // data reference index
209	              ..zeros(16)
210	              ..u16(width)
211	              ..u16(height)
212	              ..u32(0x00480000) // 72 dpi
213	              ..u32(0x00480000)
214	              ..u32(0)
215	              ..u16(1) // frame count
216	              ..zeros(32) // compressor name
217	              ..u16(0x18) // depth
218	              ..u16(0xFFFF)
219	              ..bytes_(_box('avcC', config)))
220	            .bytes,
221	      );
