146	bool _contains(Uint8List hay, List<int> needle) {
147	  outer:
148	  for (var i = 0; i + needle.length <= hay.length; i++) {
149	    for (var j = 0; j < needle.length; j++) {
150	      if (hay[i + j] != needle[j]) continue outer;
151	    }
152	    return true;
153	  }
154	  return false;
155	}
