7	/// Writes bits MSB first, with Exp-Golomb helpers (for building an SPS).
8	class _Bits {
9	  final _out = <int>[];
10	  int _cur = 0;
11	  int _n = 0;
12	
13	  void bit(int b) {
14	    _cur = (_cur << 1) | (b & 1);
15	    if (++_n == 8) {
16	      _out.add(_cur);
17	      _cur = 0;
18	      _n = 0;
19	    }
20	  }
21	
22	  void bits(int v, int n) {
23	    for (var i = n - 1; i >= 0; i--) {
24	      bit((v >> i) & 1);
25	    }
26	  }
27	
28	  void ue(int v) {
29	    final x = v + 1;
30	    final len = x.bitLength;
31	    bits(0, len - 1);
32	    bits(x, len);
33	  }
34	
35	  List<int> rbsp() {
36	    bit(1); // rbsp_stop_one_bit
37	    while (_n != 0) {
38	      bit(0);
39	    }
40	    return _out;
41	  }
42	}
