81	const _asc = [0x12, 0x10];
82	
83	class _Flv {
84	  final _b = BytesBuilder()
85	    ..add('FLV'.codeUnits)
86	    ..add([1, 5, 0, 0, 0, 9, 0, 0, 0, 0]);
87	
88	  void tag(int type, int ts, List<int> data) {
89	    final n = data.length;
90	    _b
91	      ..add([type, n >> 16 & 0xFF, n >> 8 & 0xFF, n & 0xFF])
92	      ..add([ts >> 16 & 0xFF, ts >> 8 & 0xFF, ts & 0xFF, ts >> 24 & 0xFF])
93	      ..add([0, 0, 0])
94	      ..add(data);
95	    final size = n + 11;
96	    _b.add([
97	      size >> 24 & 0xFF,
98	      size >> 16 & 0xFF,
99	      size >> 8 & 0xFF,
100	      size & 0xFF,
101	    ]);
102	  }
103	
104	  void avcHeader(List<int> avcC) => tag(9, 0, [0x17, 0, 0, 0, 0, ...avcC]);
105	
106	  void video(int ts, List<int> payload, {bool key = false, int cts = 0}) =>
107	      tag(9, ts, [
108	        key ? 0x17 : 0x27,
109	        1,
110	        cts >> 16 & 0xFF,
111	        cts >> 8 & 0xFF,
112	        cts & 0xFF,
113	        ...payload,
114	      ]);
115	
116	  void aacHeader() => tag(8, 0, [0xAF, 0, ..._asc]);
117	
118	  void audio(int ts, List<int> payload) => tag(8, ts, [0xAF, 1, ...payload]);
119	
120	  // script tag (onMetaData), ignored by the demuxer
121	  void script() => tag(18, 0, [2, 0, 10, ...'onMetaData'.codeUnits]);
122	
123	  Uint8List get bytes => _b.toBytes();
124	}
