134	/// Top-level MP4 boxes as (type, offset, size).
135	List<(String, int, int)> _boxes(Uint8List b) {
136	  final out = <(String, int, int)>[];
137	  var p = 0;
138	  while (p + 8 <= b.length) {
139	    final size = _u32(b, p);
140	    out.add((String.fromCharCodes(b, p + 4, p + 8), p, size));
141	    p += size;
142	  }
143	  return out;
144	}
