3	/// LibrePili: pure-Dart FLV demuxer feeding [Mp4Remuxer]'s progressive MP4
4	/// writer, for the old single-URL (durl) downloads.
5	///
6	/// FLV AVC payloads are already length-prefixed NAL units and AAC payloads
7	/// raw frames, which is exactly what MP4 samples hold, so sample bytes are
8	/// never decoded: every sample becomes a chunk pointing into its FLV file and
9	/// is copied byte-for-byte. Only H.264 video and AAC audio are supported;
10	/// anything else throws [UnsupportedError].
11	abstract final class _FlvDemuxer {
12	  /// A segment starting more than this before the end of what came earlier
13	  /// restarted its clock and is placed after it; a continuing segment starts
14	  /// within about a frame of that end.
15	  static const _restartToleranceMs = 100;
16	
17	  static List<_Track> demux(List<String> inputs) {
18	    final video = _FlvTrackBuilder(isVideo: true);
19	    final audio = _FlvTrackBuilder(isVideo: false);
20	    for (final input in inputs) {
21	      final raf = File(input).openSync();
22	      try {
23	        final r = _FileReader(raf);
24	        final header = r.read(0, 9);
25	        if (String.fromCharCodes(header, 0, 3) != 'FLV') {
26	          throw FormatException('not an FLV file: $input');
27	        }
28	        // header, then PreviousTagSize0
29	        var pos = ByteData.sublistView(header).getUint32(5) + 4;
30	        int? offset; // ms added to this segment's timestamps
31	        while (pos + 11 <= r.length) {
32	          final h = r.read(pos, 11);
33	          final type = h[0];
34	          final dataSize = (h[1] << 16) | (h[2] << 8) | h[3];
35	          final ts = ((h[7] << 24) | (h[4] << 16) | (h[5] << 8) | h[6])
36	              .toSigned(32);
37	          final dataPos = pos + 11;
38	          if (dataPos + dataSize > r.length) break; // truncated last tag
39	          pos = dataPos + dataSize + 4; // + PreviousTagSize
40	          final kind = type & 0x1F;
41	          if ((kind != 8 && kind != 9) || dataSize == 0) continue;
42	          if (type & 0x20 != 0) throw UnsupportedError('encrypted FLV');
43	          if (offset == null) {
44	            final end = max(video.endMs, audio.endMs);
45	            offset = end - ts > _restartToleranceMs ? end - ts : 0;
46	          }
47	          final head = r.read(dataPos, min(dataSize, 5));
48	          final time = ts + offset;
49	          if (kind == 9) {
50	            video.addVideoTag(input, dataPos, dataSize, head, time, r);
51	          } else {
52	            audio.addAudioTag(input, dataPos, dataSize, head, time, r);
53	          }
54	        }
55	      } finally {
56	        raf.closeSync();
57	      }
58	    }
59	    final starts = [
60	      for (final b in [video, audio])
61	        if (b.times.isNotEmpty) b.times.first,
62	    ];
63	    if (starts.isEmpty) throw const FormatException('no audio/video in FLV');
64	    final base = starts.reduce(min);
65	    final tracks = <_Track>[];
66	    for (final b in [video, audio]) {
67	      if (b.build(base) case final t?) tracks.add(t..index = tracks.length);
68	    }
69	    return tracks;
70	  }
71	}
72	
73	class _FlvTrackBuilder {
74	  _FlvTrackBuilder({required this.isVideo});
75	
76	  final bool isVideo;
77	
78	  /// AVCDecoderConfigurationRecord / AudioSpecificConfig.
79	  Uint8List? config;
80	
81	  // per sample, in decode order
82	  final times = <int>[]; // ms
83	  final ctsMs = <int>[];
84	  final keys = <bool>[];
85	  final paths = <String>[];
86	  final offsets = <int>[];
87	  final sizes = <int>[];
88	
89	  int get _defaultDurationMs => isVideo ? 40 : 23;
90	
91	  int get _lastDurationMs => times.length < 2
92	      ? _defaultDurationMs
93	      : times.last - times[times.length - 2];
94	
95	  /// Where the next sample of a following segment would start.
96	  int get endMs => times.isEmpty ? 0 : times.last + _lastDurationMs;
97	
98	  void addVideoTag(
99	    String path,
100	    int dataPos,
101	    int dataSize,
102	    Uint8List head,
103	    int time,
104	    _FileReader r,
105	  ) {
106	    final codec = head[0] & 0x0F;
107	    // bit 7: enhanced FLV (HEVC / AV1 ...)
108	    if (head[0] & 0x80 != 0 || codec != 7) {
109	      throw UnsupportedError('FLV video codec $codec (only H.264)');
110	    }
111	    if (dataSize <= 5) return;
112	    switch (head[1]) {
113	      case 0: // sequence header
114	        _setConfig(r.read(dataPos + 5, dataSize - 5));
115	      case 1: // NAL units
116	        final cts = ((head[2] << 16) | (head[3] << 8) | head[4]).toSigned(24);
117	        _add(path, dataPos + 5, dataSize - 5, time, cts, head[0] >> 4 == 1);
118	    }
119	  }
120	
121	  void addAudioTag(
122	    String path,
123	    int dataPos,
124	    int dataSize,
125	    Uint8List head,
126	    int time,
127	    _FileReader r,
128	  ) {
129	    final format = head[0] >> 4;
130	    if (format != 10) {
131	      throw UnsupportedError('FLV audio codec $format (only AAC)');
132	    }
133	    if (dataSize <= 2) return;
134	    switch (head[1]) {
135	      case 0: // AudioSpecificConfig
136	        _setConfig(r.read(dataPos + 2, dataSize - 2));
137	      case 1: // raw frame
138	        _add(path, dataPos + 2, dataSize - 2, time, 0, true);
139	    }
140	  }
141	
142	  void _setConfig(Uint8List c) {
143	    final old = config;
144	    if (old == null) {
145	      config = Uint8List.fromList(c);
146	      return;
147	    }
148	    var same = old.length == c.length;
149	    for (var i = 0; same && i < c.length; i++) {
150	      same = old[i] == c[i];
151	    }
152	    // repeated at segment starts; a real change would need a second stsd
153	    if (!same) {
154	      throw UnsupportedError('codec configuration changes mid-stream');
155	    }
156	  }
157	
158	  void _add(String path, int offset, int size, int time, int cts, bool key) {
159	    if (config == null) return; // undecodable before the sequence header
160	    if (times.isNotEmpty && time <= times.last) time = times.last + 1;
161	    times.add(time);
162	    ctsMs.add(cts);
163	    keys.add(key);
164	    paths.add(path);
165	    offsets.add(offset);
166	    sizes.add(size);
167	  }
168	
169	  /// [baseMs]: earliest start of all tracks; a later start becomes an empty
