3	/// LibrePili: joins progressive MP4 segments (old single-URL downloads that
4	/// come split into several files) into one timeline for [Mp4Remuxer]'s
5	/// writer. Samples are read from each segment's sample tables (stts, ctts,
6	/// stss, stsc, stsz/stz2, stco/co64) and copied byte-for-byte.
7	///
8	/// Every segment must carry the same tracks with identical codec
9	/// configuration (stsd); otherwise [UnsupportedError] is thrown and the
10	/// caller keeps the segments as separate files.
11	abstract final class _Mp4Joiner {
12	  static List<_Track> join(List<String> inputs) {
13	    final tracks = _readProgressive(inputs.first);
14	    for (final t in tracks) {
15	      _openEndedEdits(t);
16	    }
17	    for (final input in inputs.skip(1)) {
18	      final segment = _readProgressive(input);
19	      if (segment.length != tracks.length) {
20	        throw UnsupportedError('segments have different tracks: $input');
21	      }
22	      for (var i = 0; i < tracks.length; i++) {
23	        if (!_sameConfig(tracks[i], segment[i])) {
24	          throw UnsupportedError('codec configuration differs: $input');
25	        }
26	      }
27	      // start where the longest track ended, so the tracks stay in sync
28	      final start = tracks
29	          .map((t) => t.mediaDuration / t.timescale)
30	          .reduce(max);
31	      for (var i = 0; i < tracks.length; i++) {
32	        final t = tracks[i];
33	        final s = segment[i];
34	        final gap = (start * t.timescale).round() - t.mediaDuration;
35	        if (gap > 0) t.durations.last += gap;
36	        final firstSample = t.sizes.length;
37	        final dts = t.mediaDuration;
38	        for (final c in s.chunks) {
39	          t.chunks.add(
40	            _Chunk(
41	                t,
42	                c.sourceOffset,
43	                c.firstSample + firstSample,
44	                c.startDts + dts,
45	                c.sourcePath,
46	              )
47	              ..length = c.length
48	              ..sampleCount = c.sampleCount,
49	          );
50	        }
51	        t
52	          ..durations.addAll(s.durations)
53	          ..sizes.addAll(s.sizes)
54	          ..ctos.addAll(s.ctos)
55	          ..syncs.addAll(s.syncs);
56	      }
57	    }
58	    return tracks;
59	  }
60	
61	  static bool _sameConfig(_Track a, _Track b) {
62	    if (a.sampleEntryType != b.sampleEntryType ||
63	        a.timescale != b.timescale ||
64	        a.stsd.length != b.stsd.length) {
65	      return false;
66	    }
67	    for (var i = 0; i < a.stsd.length; i++) {
68	      if (a.stsd[i] != b.stsd[i]) return false;
69	    }
70	    return true;
71	  }
72	
73	  /// The first segment's edit list is kept (encoder delay, a late start),
74	  /// but its playing edit must run to the end of the joined track.
75	  static void _openEndedEdits(_Track t) {
76	    final firstPlaying = t.edits.indexWhere((e) => e.mediaTime >= 0);
77	    if (firstPlaying == -1) {
78	      t.edits.clear();
79	      return;
80	    }
81	    final playing = t.edits[firstPlaying];
82	    t.edits
83	      ..removeRange(firstPlaying, t.edits.length)
84	      ..add(_EditEntry(0, playing.mediaTime, playing.rate));
85	  }
86	
87	  static List<_Track> _readProgressive(String path) {
88	    final raf = File(path).openSync();
89	    Uint8List? moov;
90	    try {
91	      final length = raf.lengthSync();
92	      var pos = 0;
93	      while (pos + 8 <= length) {
94	        raf.setPositionSync(pos);
95	        final header = raf.readSync(16);
96	        final hd = ByteData.sublistView(header);
97	        var size = hd.getUint32(0);
98	        final type = String.fromCharCodes(header, 4, 8);
99	        var headerSize = 8;
100	        if (size == 1) {
101	          size = hd.getUint64(8);
102	          headerSize = 16;
103	        } else if (size == 0) {
104	          size = length - pos;
105	        }
106	        if (size < headerSize || pos + size > length) {
107	          throw FormatException('bad box $type at $pos in $path');
108	        }
109	        if (type == 'moov') {
110	          raf.setPositionSync(pos + headerSize);
111	          moov = raf.readSync(size - headerSize);
112	        } else if (type == 'moof') {
113	          throw UnsupportedError('fragmented MP4 segment: $path');
114	        }
115	        pos += size;
116	      }
117	    } finally {
118	      raf.closeSync();
119	    }
120	    if (moov == null) throw FormatException('no moov in $path');
121	
122	    var movieTimescale = Mp4Remuxer._movieTimescale;
123	    final traks = <Uint8List>[];
124	    for (final (type, body) in _R(moov).boxes()) {
125	      if (type == 'mvhd') {
126	        final b = _R(body);
127	        final v = b.u8();
128	        b.skip(3 + (v == 1 ? 16 : 8));
129	        movieTimescale = b.u32();
130	      } else if (type == 'trak') {
131	        traks.add(body);
132	      }
133	    }
134	    final tracks = <_Track>[];
135	    for (final trak in traks) {
136	      final t = _Track(path)..sourceMovieTimescale = movieTimescale;
137	      t._parseTrak(trak);
138	      _readSampleTables(t, trak);
139	      if (t.sizes.isNotEmpty) tracks.add(t..index = tracks.length);
140	    }
141	    if (tracks.isEmpty) throw FormatException('no samples in $path');
142	    return tracks;
143	  }
144	
145	  static Map<String, Uint8List> _stbl(Uint8List trak) {
146	    for (final (type, mdia) in _R(trak).boxes()) {
147	      if (type != 'mdia') continue;
148	      for (final (t2, minf) in _R(mdia).boxes()) {
149	        if (t2 != 'minf') continue;
150	        for (final (t3, stbl) in _R(minf).boxes()) {
151	          if (t3 == 'stbl')
152	            return {for (final (k, v) in _R(stbl).boxes()) k: v};
153	        }
154	      }
155	    }
156	    return const {};
157	  }
158	
159	  static void _readSampleTables(_Track t, Uint8List trak) {
160	    final stbl = _stbl(trak);
161	
162	    // sample sizes
163	    final sizes = <int>[];
164	    if (stbl['stsz'] case final body?) {
165	      final b = _R(body)..skip(4);
166	      final fixed = b.u32();
167	      final n = b.u32();
168	      for (var i = 0; i < n; i++) {
169	        sizes.add(fixed != 0 ? fixed : b.u32());
170	      }
171	    } else if (stbl['stz2'] case final body?) {
172	      final b = _R(body)..skip(7);
173	      final field = b.u8();
174	      final n = b.u32();
175	      for (var i = 0; i < n; i++) {
176	        switch (field) {
177	          case 4:
178	            final byte = b.data[b.pos + (i >> 1)];
179	            sizes.add(i.isEven ? byte >> 4 : byte & 0xF);
180	          case 8:
181	            sizes.add(b.u8());
182	          case 16:
183	            sizes.add((b.u8() << 8) | b.u8());
184	          default:
185	            throw FormatException('bad stz2 field size $field');
186	        }
187	      }
188	    }
189	    if (sizes.isEmpty) return;
190	    final n = sizes.length;
191	
192	    // decode durations
193	    final durations = <int>[];
194	    if (stbl['stts'] case final body?) {
195	      final b = _R(body)..skip(4);
196	      final entries = b.u32();
197	      for (var i = 0; i < entries && durations.length < n; i++) {
198	        final count = b.u32();
199	        final delta = b.u32();
200	        for (var j = 0; j < count && durations.length < n; j++) {
201	          durations.add(delta);
202	        }
203	      }
204	    }
205	    while (durations.length < n) {
206	      durations.add(durations.isEmpty ? 0 : durations.last);
207	    }
208	
209	    // composition offsets
210	    final ctos = <int>[];
211	    if (stbl['ctts'] case final body?) {
212	      final b = _R(body);
213	      final signed = b.u8() == 1;
214	      b.skip(3);
215	      final entries = b.u32();
216	      for (var i = 0; i < entries && ctos.length < n; i++) {
217	        final count = b.u32();
218	        final offset = signed ? b.i32() : b.u32();
219	        for (var j = 0; j < count && ctos.length < n; j++) {
220	          ctos.add(offset);
221	        }
222	      }
223	    }
224	    while (ctos.length < n) {
225	      ctos.add(0);
226	    }
227	
228	    // sync samples (no stss: every sample is a sync sample)
229	    final syncs = List.filled(n, true);

