44	/// Baseline SPS for [widthMbs] x [heightMbs] macroblocks, optional bottom
45	/// crop (in crop units).
46	List<int> _sps(int widthMbs, int heightMbs, {int cropBottom = 0}) {
47	  final b = _Bits()
48	    ..bits(66, 8) // profile_idc baseline
49	    ..bits(0, 8) // constraint flags
50	    ..bits(30, 8) // level
51	    ..ue(0) // sps id
52	    ..ue(0) // log2_max_frame_num_minus4
53	    ..ue(2) // pic_order_cnt_type
54	    ..ue(1) // max_num_ref_frames
55	    ..bit(0) // gaps
56	    ..ue(widthMbs - 1)
57	    ..ue(heightMbs - 1)
58	    ..bit(1) // frame_mbs_only
59	    ..bit(1); // direct_8x8_inference
60	  if (cropBottom > 0) {
61	    b
62	      ..bit(1)
63	      ..ue(0)
64	      ..ue(0)
65	      ..ue(0)
66	      ..ue(cropBottom);
67	  } else {
68	    b.bit(0);
69	  }
70	  b.bit(0); // vui
71	  return [0x67, ...b.rbsp()];
72	}
