+      for (var i = 0; i < tracks.length; i++) {
+        final t = tracks[i];
+        final s = segment[i];
+        final gap = (start * t.timescale).round() - t.mediaDuration;
+        if (gap > 0) t.durations.last += gap;
+        final firstSample = t.sizes.length;
+        final dts = t.mediaDuration;
+        for (final c in s.chunks) {
