+    final ctos = <int>[];
+    if (stbl['ctts'] case final body?) {
+      final b = _R(body);
+      final signed = b.u8() == 1;
+      b.skip(3);
+      final entries = b.u32();
+      for (var i = 0; i < entries && ctos.length < n; i++) {
+        final count = b.u32();
+        final offset = signed ? b.i32() : b.u32();
+        for (var j = 0; j < count && ctos.length < n; j++) {
+          ctos.add(offset);
+        }
+      }
+    }
+    while (ctos.length < n) {
+      ctos.add(0);
+    }
