+      while (entry + 1 < stsc.length && stsc[entry + 1].$1 <= c) {
+        entry++;
+      }
+      final chunk = _Chunk(t, offsets[c], sample, dts);
+      for (var j = 0; j < stsc[entry].$2 && sample < n; j++) {
+        chunk
